# TASK: reconciliacion de ventas manuales en Ganesha — backup + compile + test + reporte
import base64,hashlib,json,os,py_compile,re,subprocess,time,urllib.request
B="/home/opc/bot_semillas"
FILES={'ganesha_ejecutor.py': ('ganesha_ejecutor.py.bak.pre_rec', ''), 'ejecutor_dash.py': ('ejecutor_dash.py.bak.pre_rec', ''), 'loop_analista.py': ('loop_analista.py.bak.v2', '')}
def scrub(s):
    if not s: return s
    s=re.sub(r"(github_pat_[A-Za-z0-9_]+|gh[posru]_[A-Za-z0-9]+|sk-ant-[A-Za-z0-9_\-]+)","<TOK>",s)
    return re.sub(r"[A-Za-z0-9]{56,}","<REDACTED>",s)
tok=""
try:
    for L in open(B+"/.env"):
        m=re.search(r"(github_pat_[A-Za-z0-9_]+|gh[posru]_[A-Za-z0-9]+)",L)
        if m: tok=m.group(1)
except Exception: pass
info={"task":"install_ganesha_reconcile","now":time.strftime("%Y-%m-%d %H:%M:%SZ",time.gmtime()),"pasos":[]}
def step(s): info["pasos"].append(s); print("[reconcile-install]",s)
try:
    tmps=[]
    for name,(bak,b64) in FILES.items():
        src=base64.b64decode(b64)
        info.setdefault("sha256",{})[name]=hashlib.sha256(src).hexdigest()[:16]
        tmp=B+"/_new_"+name
        open(tmp,"wb").write(src)
        py_compile.compile(tmp,doraise=True)
        step("compile OK %s (%d bytes)"%(name,len(src)))
        tmps.append((tmp,name,bak))
    for tmp,name,bak in tmps:
        tgt=B+"/"+name
        if os.path.exists(tgt) and not os.path.exists(B+"/"+bak):
            open(B+"/"+bak,"wb").write(open(tgt,"rb").read()); step("backup -> "+bak)
        os.replace(tmp,tgt); step("instalado "+name)
    test=("import sys; sys.path.insert(0,%r); import ganesha_ejecutor as G;"
          "assert hasattr(G,'reconcile_manual'), 'falta reconcile_manual';"
          "assert 'breakeven_r' not in G.P, 'no debia haber regla breakeven';"
          "import loop_analista as A; t,o=A.consolidate(); m=A.rolling_metrics(t);"
          "import json; print(json.dumps({'reconcile':'presente',"
          "'finales':sum(1 for x in t if x.get('final')),"
          "'abiertas':sorted(o.keys()),"
          "'ganesha_hist':m['ganesha']['historico']}))")%B
    r=subprocess.run([B+"/venv/bin/python","-c",test],capture_output=True,text=True,timeout=180,cwd=B)
    info["test_stdout"]=scrub(r.stdout[-1500:]); info["test_stderr"]=scrub(r.stderr[-800:])
    step("test rc=%d"%r.returncode)
    info["ok"]=(r.returncode==0)
except Exception as e:
    info["ok"]=False; info["error"]=scrub(str(e)[:300])
U="https://api.github.com/repos/calcagnoagustin/radar/contents/docs/_diag.json"
def R(m,d=None):
    q=urllib.request.Request(U,data=d,method=m); q.add_header("Authorization","token "+tok); q.add_header("User-Agent","recinstall")
    return urllib.request.urlopen(q,timeout=30).read()
sha=None
try: sha=json.loads(R("GET")).get("sha")
except Exception: pass
p={"message":"install ganesha reconcile","content":base64.b64encode(json.dumps(info,indent=1).encode()).decode()}
if sha: p["sha"]=sha
try: R("PUT",json.dumps(p).encode()); print("REPORTADO ok=%s"%info.get("ok"))
except Exception as e: print("PUSH_ERR",e)
